import React from "react";
import {
  AbsoluteFill,
  Sequence,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Img,
  staticFile,
} from "remotion";
import { BRAND, BRAND_FONT_FACE_CSS } from "../theme";
import {
  springIn,
  staggerChild,
  compoundReveal,
  sceneExit,
  ambientDrift,
  drawPath,
  SPRINGS,
  TIMING,
} from "../motion";
import { RegistrationFrame, ContourField, DottedField, IsoWireframe, TagPill } from "../decor";

// =============================================================================
// "The Ledger Handshake" — premium transparent overlay for the x402 / Apify
// agent-payment demo. Money is the protagonist; one orange request-line spines
// the whole piece. Built to composite over A-roll: the ROOT AbsoluteFill has NO
// background (so the transparent export keeps a clean alpha channel), and every
// element is an opaque BRAND.colors.card panel. Orange is the only accent;
// orangeDeep (#FF4800) fires exactly twice (allowance first-advance + the 402).
// =============================================================================

export const fps = 25;

const C = BRAND.colors;
const FONT = BRAND.fonts.marketing;       // GT Walsheim (display)
const BODY = BRAND.fonts.primary;         // Inter
const MONO = "ui-monospace, 'SF Mono', Menlo, monospace";

// ---- beat windows (frames @ 25fps) -----------------------------------------
const B = {
  capability: { from: 0, dur: 225 },
  pivot: { from: 225, dur: 100 },
  x402: { from: 325, dur: 150 },
  lower: { from: 300, dur: 175 },
  hero402: { from: 475, dur: 475 },
  allowance: { from: 950, dur: 500 },
  handshake: { from: 1450, dur: 500 },
  clockworks: { from: 1950, dur: 550 },
  metrics: { from: 2500, dur: 700 },
  scale: { from: 3200, dur: 550 },
  finale: { from: 3750, dur: 505 },
};

// ---- small helpers ----------------------------------------------------------
function card(base: number): React.CSSProperties {
  return {
    backgroundColor: C.card,
    border: `1px solid ${C.border}`,
    borderRadius: base * 0.014,
    boxShadow: `0 ${base * 0.011}px ${base * 0.03}px rgba(0,0,0,0.45)`,
  };
}

function countUp(frame: number, vfps: number, value: number, delay: number): number {
  const p = spring({ frame, fps: vfps, delay, config: SPRINGS.LIQUID });
  return Math.round(interpolate(p, [0, 1], [0, value]));
}

const fmt = (n: number) => n.toLocaleString("en-US");

const LineIcon: React.FC<{
  paths: string[];
  size: number;
  color?: string;
  sw?: number;
  style?: React.CSSProperties;
}> = ({ paths, size, color = "currentColor", sw = 1.4, style }) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 16 16"
    fill="none"
    stroke={color}
    strokeWidth={sw}
    strokeLinecap="round"
    strokeLinejoin="round"
    style={style}
  >
    {paths.map((d, i) => (
      <path key={i} d={d} />
    ))}
  </svg>
);

const DrawCheck: React.FC<{ size: number; frame: number; vfps: number; delay: number }> = ({
  size,
  frame,
  vfps,
  delay,
}) => {
  const draw = drawPath(frame, vfps, 16, { delay, preset: "SNAPPY" });
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none" stroke={C.orange} strokeWidth={2.1} strokeLinecap="round" strokeLinejoin="round">
      <path d="M3.5 8.2l2.8 2.8 6.2-6.4" {...draw} />
    </svg>
  );
};

const ApifySymbol: React.FC<{ size: number; style?: React.CSSProperties }> = ({ size, style }) => (
  <Img
    src={staticFile("assets/apify/Apify symbol white.svg")}
    style={{ width: size, height: size, objectFit: "contain", ...style }}
  />
);

// A small opaque "value capsule": orange left tick-rule + a number/label.
const ValueCapsule: React.FC<{
  base: number;
  value: React.ReactNode;
  label?: string;
  accent?: boolean;
  style?: React.CSSProperties;
}> = ({ base, value, label, accent, style }) => (
  <div
    style={{
      ...card(base),
      display: "inline-flex",
      flexDirection: "column",
      justifyContent: "center",
      padding: `${base * 0.016}px ${base * 0.022}px`,
      borderLeft: `${Math.max(3, base * 0.0035)}px solid ${C.orange}`,
      gap: base * 0.004,
      ...style,
    }}
  >
    <div
      style={{
        fontFamily: FONT,
        fontWeight: 700,
        fontSize: base * 0.034,
        color: accent ? C.orange : C.text,
        letterSpacing: "-0.03em",
        lineHeight: 1,
        fontVariantNumeric: "tabular-nums",
        whiteSpace: "nowrap",
      }}
    >
      {value}
    </div>
    {label && (
      <div
        style={{
          fontFamily: BODY,
          fontWeight: 500,
          fontSize: base * 0.015,
          color: C.textSubtle,
          letterSpacing: "0.06em",
          textTransform: "uppercase",
          whiteSpace: "nowrap",
        }}
      >
        {label}
      </div>
    )}
  </div>
);

// Allowance meter that fills to `fillTo` (0..1) and stops; one-shot orangeDeep
// leading-edge heat when `flash` is on (only used on its FIRST appearance).
const AllowanceMeter: React.FC<{
  base: number;
  trackWidth: number;
  fillTo: number;
  frame: number;
  vfps: number;
  delay: number;
  flash?: boolean;
}> = ({ base, trackWidth, fillTo, frame, vfps, delay, flash }) => {
  const p = springIn(frame, vfps, delay, "LIQUID");
  const w = p * fillTo;
  const edgeColor = flash
    ? (interpolate(p, [0, 0.6, 1], [0, 1, 1]) < 0.6 ? C.orangeDeep : C.orange)
    : C.orange;
  const h = base * 0.012;
  return (
    <div
      style={{
        position: "relative",
        width: trackWidth,
        height: h,
        borderRadius: h,
        background: C.orangeTint, // low-alpha track — legal because it's inside an opaque card
        overflow: "hidden",
      }}
    >
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          bottom: 0,
          width: `${w * 100}%`,
          background: `linear-gradient(90deg, ${C.orange}, ${edgeColor})`,
          borderRadius: h,
          boxShadow: flash && p < 0.6 ? `0 0 ${h * 2}px ${C.orangeDeep}` : "none",
        }}
      />
    </div>
  );
};

// Full-frame hero scaffold: large opaque card centered on transparent ground
// (export-safe — NOT a #161718 fill) + registration brackets.
const HeroPanel: React.FC<{
  dur: number;
  wFrac?: number;
  minHFrac?: number;
  dotted?: boolean;
  contour?: boolean;
  noExit?: boolean;
  children: React.ReactNode;
}> = ({ dur, wFrac = 0.6, minHFrac = 0.46, dotted, contour, noExit, children }) => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);
  const reveal = compoundReveal(frame, vfps, {
    delay: 2,
    preset: "LIQUID",
    translateY: base * 0.018,
    scaleFrom: 0.93,
    blurFrom: 10,
  });
  const exit = noExit ? { opacity: 1, transform: "none" } : sceneExit(frame, dur);
  return (
    <AbsoluteFill
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        opacity: exit.opacity,
        transform: exit.transform,
      }}
    >
      {contour && <ContourField position="center" opacity={0.32} delay={6} />}
      <div
        style={{
          position: "relative",
          width: width * wFrac,
          minHeight: height * minHFrac,
          ...card(base),
          padding: base * 0.055,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          overflow: "hidden",
          opacity: reveal.opacity,
          transform: reveal.transform,
          filter: reveal.filter,
        }}
      >
        {dotted && <DottedField opacity={0.07} style={{ inset: 0, height: "100%" }} />}
        <div style={{ position: "relative", display: "flex", flexDirection: "column", alignItems: "center", width: "100%" }}>
          {children}
        </div>
      </div>
    </AbsoluteFill>
  );
};

// =============================================================================
// BEAT 4 — speaker lower-thirds (dual), mirrors LowerThird PersonCard recipe
// =============================================================================
const PersonCard: React.FC<{ name: string; title: string; align: "left" | "right"; dur: number }> = ({ name, title, align, dur }) => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);
  const cardP = springIn(frame, vfps, 5, "LIQUID");
  const nameP = springIn(frame, vfps, 28, "SNAPPY");
  const lineP = springIn(frame, vfps, 36, "ELASTIC");
  const titleP = springIn(frame, vfps, 43, "GENTLE");
  const exit = sceneExit(frame, dur);
  const offIn = interpolate(cardP, [0, 1], [base * 0.05, 0]);
  return (
    <div style={{ opacity: Math.min(cardP, exit.opacity), transform: `translateY(${offIn}px) ${exit.transform === "none" ? "" : exit.transform}` }}>
      <div style={{ ...card(base), borderRadius: base * 0.008, padding: `${base * 0.022}px ${base * 0.034}px` }}>
        <div style={{ display: "flex", flexDirection: "column", gap: base * 0.006, alignItems: align === "right" ? "flex-end" : "flex-start" }}>
          <div style={{ opacity: nameP, fontFamily: FONT, fontWeight: 700, fontSize: base * 0.030, color: C.text, lineHeight: 1, whiteSpace: "nowrap", letterSpacing: "0.005em" }}>{name}</div>
          <div style={{ width: `${interpolate(lineP, [0, 1], [0, 100])}%`, height: Math.max(2, base * 0.0016), background: C.orange, borderRadius: 2, opacity: titleP, alignSelf: align === "right" ? "flex-end" : "flex-start" }} />
          <div style={{ opacity: titleP, fontFamily: BODY, fontWeight: 500, fontSize: base * 0.020, color: C.orange, lineHeight: 1, whiteSpace: "nowrap", letterSpacing: "0.01em" }}>{title}</div>
        </div>
      </div>
    </div>
  );
};

const BeatLowerThirds: React.FC = () => {
  const { width, height } = useVideoConfig();
  const base = Math.min(width, height);
  return (
    <AbsoluteFill style={{ display: "flex", flexDirection: "row", alignItems: "flex-end", justifyContent: "space-between", padding: `0 ${base * 0.046}px ${base * 0.085}px ${base * 0.046}px` }}>
      <PersonCard name="Stepan" title="Core Services · x402 payment flow" align="left" dur={B.lower.dur} />
      <PersonCard name="Jakub Kopecký" title="Engineer at AI" align="right" dur={B.lower.dur} />
    </AbsoluteFill>
  );
};

export const durationInFrames = 175;
export default BeatLowerThirds;
